Connect it to your node branch
Make trail_interfaces a dependency of the Python or C++ pub/sub package you completed.

Python branch
Add &lt;exec_depend&gt;trail_interfaces&lt;/exec_depend&gt; to package.xml. In both Python nodes replace their contents with these complete files.
publisher.py:
import rclpy
from rclpy.node import Node
from trail_interfaces.msg import Waypoint

class WaypointPublisher(Node):
    def __init__(self):
        super().__init__('waypoint_publisher')
        self.publisher = self.create_publisher(Waypoint, 'goal', 10)
        self.x = 0.0
        self.create_timer(0.5, self.publish_waypoint)
    def publish_waypoint(self):
        message = Waypoint(frame_id='map', x=self.x, y=0.0)
        self.publisher.publish(message)
        self.get_logger().info(f'goal map ({message.x}, {message.y})')
        self.x += 1.0

def main():
    rclpy.init(); node = WaypointPublisher(); rclpy.spin(node)
subscriber.py:
import rclpy
from rclpy.node import Node
from trail_interfaces.msg import Waypoint

def main():
    rclpy.init(); node = Node('waypoint_listener')
    node.create_subscription(Waypoint, 'goal', lambda msg:
        node.get_logger().info(f'goal {msg.frame_id} ({msg.x}, {msg.y})'), 10)
    rclpy.spin(node)
Keep the existing counter and listener console-script names, then build:
cd ~/ros2_trails_ws
colcon build --packages-up-to trail_py_pubsub
source install/local_setup.bash


C++ branch
Add &lt;depend&gt;trail_interfaces&lt;/depend&gt; to package.xml. In CMakeLists.txt, add find_package(trail_interfaces REQUIRED) and include trail_interfaces in ament_target_dependencies for both targets. Replace counter.cpp with:
#include &lt;chrono&gt;
#include &lt;memory&gt;
#include "rclcpp/rclcpp.hpp"
#include "trail_interfaces/msg/waypoint.hpp"
using namespace std::chrono_literals;
int main(int argc, char ** argv) {
  rclcpp::init(argc, argv);
  auto node = std::make_shared&lt;rclcpp::Node&gt;("waypoint_publisher");
  auto pub = node-&gt;create_publisher&lt;trail_interfaces::msg::Waypoint&gt;("goal", 10);
  double x = 0.0;
  auto timer = node-&gt;create_wall_timer(500ms, [node, pub, &x]() {
    trail_interfaces::msg::Waypoint msg;
    msg.frame_id = "map"; msg.x = x++; msg.y = 0.0;
    pub-&gt;publish(msg);
    RCLCPP_INFO(node-&gt;get_logger(), "goal %s (%.1f, %.1f)", msg.frame_id.c_str(), msg.x, msg.y);
  });
  rclcpp::spin(node); rclcpp::shutdown();
}
Replace listener.cpp with:
#include &lt;memory&gt;
#include "rclcpp/rclcpp.hpp"
#include "trail_interfaces/msg/waypoint.hpp"
int main(int argc, char ** argv) {
  rclcpp::init(argc, argv);
  auto node = std::make_shared&lt;rclcpp::Node&gt;("waypoint_listener");
  auto sub = node-&gt;create_subscription&lt;trail_interfaces::msg::Waypoint&gt;(
    "goal", 10, [node](trail_interfaces::msg::Waypoint::ConstSharedPtr msg) {
      RCLCPP_INFO(node-&gt;get_logger(), "goal %s (%.1f, %.1f)", msg-&gt;frame_id.c_str(), msg-&gt;x, msg-&gt;y);
    });
  rclcpp::spin(node); rclcpp::shutdown();
}
Then build:
cd ~/ros2_trails_ws
colcon build --packages-up-to trail_cpp_pub
source install/local_setup.bash
Run both nodes from your chosen branch, then verify ros2 topic type /goal prints trail_interfaces/msg/Waypoint and the subscriber logs frame_id, x, and y. If compilation or import fails, first confirm ros2 interface show trail_interfaces/msg/Waypoint works in that terminal. The declared dependency creates an edge in the package graph; this is what lets colcon --packages-up-to build trail_interfaces before the consuming node package.

Do it
source /opt/ros/jazzy/setup.bash
cd ~/ros2_trails_ws/src
ros2 pkg create --build-type ament_cmake --license Apache-2.0 \
  --dependencies rclcpp std_msgs trail_cpp_pub
The generated locations used below are:
trail_cpp_pub/
├── CMakeLists.txt
├── package.xml
└── src/
    ├── counter.cpp
    └── listener.cpp
Create trail_cpp_pub/src/counter.cpp:
#include &lt;chrono&gt;
#include &lt;memory&gt;
#include "rclcpp/rclcpp.hpp"
#include "std_msgs/msg/int32.hpp"
using namespace std::chrono_literals;

int main(int argc, char ** argv) {
  rclcpp::init(argc, argv);
  auto node = std::make_shared&lt;rclcpp::Node&gt;("cpp_counter");
  auto pub = node-&gt;create_publisher&lt;std_msgs::msg::Int32&gt;("cpp_count", 10);
  int value = 0;
  auto timer = node-&gt;create_wall_timer(500ms, [node, pub, &value]() {
    std_msgs::msg::Int32 msg; msg.data = value++;
    pub-&gt;publish(msg);
    RCLCPP_INFO(node-&gt;get_logger(), "published %d", msg.data);
  });
  rclcpp::spin(node);
  rclcpp::shutdown();
}
Add to CMakeLists.txt before ament_package():
add_executable(counter src/counter.cpp)
ament_target_dependencies(counter rclcpp std_msgs)
install(TARGETS counter DESTINATION lib/${PROJECT_NAME})
Create trail_cpp_pub/src/listener.cpp:
#include &lt;memory&gt;
#include "rclcpp/rclcpp.hpp"
#include "std_msgs/msg/int32.hpp"

int main(int argc, char ** argv) {
  rclcpp::init(argc, argv);
  auto node = std::make_shared&lt;rclcpp::Node&gt;("cpp_listener");
  auto sub = node-&gt;create_subscription&lt;std_msgs::msg::Int32&gt;(
    "cpp_count", 10, [node](std_msgs::msg::Int32::ConstSharedPtr msg) {
      RCLCPP_INFO(node-&gt;get_logger(), "received %d", msg-&gt;data);
    });
  rclcpp::spin(node);
  rclcpp::shutdown();
}
Add and install the second target:
add_executable(listener src/listener.cpp)
ament_target_dependencies(listener rclcpp std_msgs)
install(TARGETS counter listener DESTINATION lib/${PROJECT_NAME})
Build and source the workspace. Run ros2 run trail_cpp_pub counter and ros2 run trail_cpp_pub listener in separate sourced terminals. The listener should log the same increasing values produced by the publisher.

